/**
 * Generates src/lib/contracts/types.gen.ts from the JSON Schemas in contracts/schema (SPEC §2.6,
 * §3.3, §7.6: "types generated by json-schema-to-typescript").
 *
 * The generator is pure: it takes a reader for the schema files and returns the file text, so the
 * same code runs from the command line (scripts/gen-types.ts, `make gen-types`) and from the drift
 * test (types.gen.test.ts). Nothing here touches the file system; `$ref`s between schemas are
 * resolved through the reader. It is build tooling (json-schema-to-typescript needs Node): app code
 * imports types.gen.ts, never this module.
 *
 * Naming: schema titles become type names (EvaluatorSpec, PolicyDoc, RouteSettings, ...). The shared
 * definitions of common.v1 carry no titles, so each is named after its `$defs` key (PolicyMode,
 * RawAnswer, ...) and emitted once.
 */
import { compile, type Options } from 'json-schema-to-typescript';

/** The shared definitions file; each of its `$defs` becomes one exported type. */
export const COMMON_SCHEMA = 'common.v1.schema.json';

/**
 * The schema files whose root types are generated, in output order. api.v1 is not listed: it is
 * itself generated from src/types/api.ts (contracts/tools/api-schema).
 */
export const TYPE_SCHEMAS = [
  'evaluator.v1.schema.json',
  'evaluator-draft.v1.schema.json',
  'question-set.v1.schema.json',
  'policy.v1.schema.json',
  'calibration.v1.schema.json',
  'benchmark-run.v1.schema.json',
  'decide-input.v1.schema.json',
  'decision.v1.schema.json',
  'evidence-summary.v1.schema.json',
  'vector.v1.schema.json',
] as const;

/** Reads one parsed schema file by its file name (for example "policy.v1.schema.json"). */
export type SchemaReader = (fileName: string) => unknown;

const BUNDLE = 'ContractTypesBundle';
// A base URL that no real file lives under: every $ref resolves through the reader.
const BASE = 'contracts:/schema/';

const BANNER = `/* eslint-disable */
/**
 * GENERATED FILE: do not edit. Produced by json-schema-to-typescript from contracts/schema
 * (src/lib/contracts/generate.ts). Regenerate with \`make gen-types\`; types.gen.test.ts fails when
 * this file and the schemas drift apart. Schema titles are the type names.
 */`;

type JsonObject = Record<string, unknown>;

const isObject = (v: unknown): v is JsonObject => typeof v === 'object' && v !== null && !Array.isArray(v);

// common.v1 definitions whose `$defs` key would shadow a global type.
const RENAMED_COMMON: Record<string, string> = { Date: 'ISODate' };

/** Gives every untitled common.v1 definition its `$defs` key as title, so it is emitted by name. */
function titleCommonDefinitions(schema: unknown): unknown {
  const copy = structuredClone(schema);
  if (isObject(copy) && isObject(copy.$defs)) {
    for (const [key, def] of Object.entries(copy.$defs)) {
      if (isObject(def) && typeof def.title !== 'string') def.title = RENAMED_COMMON[key] ?? key;
    }
  }
  return copy;
}

// Keywords that only annotate a schema; next to a `$ref` they do not change what it accepts.
const ANNOTATIONS = new Set(['$ref', 'title', 'description', '$comment', 'default', 'examples', 'deprecated', 'readOnly', 'writeOnly']);

/**
 * A `$ref` with sibling annotations (a property's own description or default) is a different schema
 * object from the definition it references, which json-schema-to-typescript would emit a second
 * time under a numbered name (CalibrationTable1, FailMode1). Dropping the annotations keeps one type
 * per definition; the definition's own description still documents it.
 */
function stripRefAnnotations(node: unknown): unknown {
  if (Array.isArray(node)) return node.map(stripRefAnnotations);
  if (!isObject(node)) return node;
  const out: JsonObject = {};
  const annotationsOnly = typeof node.$ref === 'string' && Object.keys(node).every((k) => ANNOTATIONS.has(k));
  for (const [k, v] of Object.entries(node)) {
    if (annotationsOnly && k !== '$ref') continue;
    // enum, const, default and examples hold data, not schemas.
    const data = k === 'enum' || k === 'const' || k === 'default' || k === 'examples';
    Object.defineProperty(out, k, { value: data ? v : stripRefAnnotations(v), enumerable: true, writable: true, configurable: true });
  }
  return out;
}

function prepare(fileName: string, read: SchemaReader): unknown {
  const schema = read(fileName);
  if (!isObject(schema)) throw new Error(`${fileName}: not a JSON Schema object`);
  return stripRefAnnotations(fileName === COMMON_SCHEMA ? titleCommonDefinitions(schema) : schema);
}

/** Generates the text of types.gen.ts. */
export async function generateTypesGen(read: SchemaReader): Promise<string> {
  const cache = new Map<string, string>();
  const load = (fileName: string): string => {
    let text = cache.get(fileName);
    if (text === undefined) {
      text = JSON.stringify(prepare(fileName, read));
      cache.set(fileName, text);
    }
    return text;
  };

  const common = read(COMMON_SCHEMA);
  const commonDefs = isObject(common) && isObject(common.$defs) ? Object.keys(common.$defs).sort() : [];
  const properties: JsonObject = {};
  for (const file of TYPE_SCHEMAS) properties[file] = { $ref: file };
  for (const def of commonDefs) properties[`common:${def}`] = { $ref: `${COMMON_SCHEMA}#/$defs/${def}` };
  const bundle = { title: BUNDLE, type: 'object', additionalProperties: false, properties };

  const options: Partial<Options> = {
    cwd: BASE,
    bannerComment: '',
    additionalProperties: false,
    unknownAny: true,
    strictIndexSignatures: false,
    ignoreMinAndMaxItems: true,
    maxItems: -1,
    unreachableDefinitions: false,
    format: true,
    style: { singleQuote: true, printWidth: 110, trailingComma: 'all' },
    $refOptions: {
      resolve: {
        file: false,
        http: false,
        contracts: {
          order: 1,
          canRead: (file: { url: string }) => file.url.startsWith(BASE),
          read: (file: { url: string }) => load(decodeURIComponent(file.url.slice(BASE.length))),
        },
      },
    },
  };
  const ts = await compile(bundle as Parameters<typeof compile>[0], BUNDLE, options);

  // The bundle only exists to pull every root into one compilation; it is not a contract type.
  const bundleDecl = new RegExp(`\\nexport interface ${BUNDLE} \\{\\n[\\s\\S]*?\\n\\}\\n`);
  if (!bundleDecl.test(ts)) throw new Error(`generate: ${BUNDLE} declaration not found`);
  return `${BANNER}\n${ts.replace(bundleDecl, '\n').trim()}\n`;
}
